#' Load the bundled single-cell example data
#'
#' A synthetic multiome-style dataset on the toy chromosome of
#' [locusPickExample()]: 400 cells from 8 samples (WT/KO x young/old, two
#' replicates) and two cell types, with RNA counts, a tabix-indexed ATAC
#' fragments file and peak-gene links. Generated by
#' `inst/scripts/make_singlecell_example.R`.
#'
#' @param seurat If `TRUE` and Seurat, SeuratObject and Signac are installed,
#'   also return `object`: a Seurat object with an `RNA` assay and a Signac
#'   `ATAC` assay (fragments and links attached).
#' @return A list with `rna` (genes x cells counts), `meta` (cell metadata),
#'   `fragments` (path), `peaks` (`GRanges`), `links` (`data.frame`),
#'   `genes` (gene models) and, optionally, `object`.
#' @examples
#' sc <- locusPickSingleCellExample()
#' table(sc$meta$cell_type, sc$meta$sample)
#' @export
locusPickSingleCellExample <- function(seurat = FALSE) {
    f <- function(x) system.file("extdata", x, package = "LocusPick", mustWork = TRUE)
    meta <- utils::read.delim(f("toy_sc_meta.tsv"), stringsAsFactors = FALSE)
    rownames(meta) <- meta$barcode
    out <- list(rna = readRDS(f("toy_sc_rna.rds")), meta = meta,
                fragments = f("toy_sc_fragments.tsv.gz"),
                peaks = asPeaks(f("toy_peaks.bed")),
                links = utils::read.delim(f("toy_sc_links.tsv"), stringsAsFactors = FALSE),
                genes = readGeneModels(f("toy.gtf")))
    if (seurat) {
        for (p in c("SeuratObject", "Signac")) .requirePkg(p, "for seurat = TRUE")
        so <- .requireCall("SeuratObject", "CreateSeuratObject")(
            out$rna, assay = "RNA", meta.data = meta[, -1])
        pk <- GenomicRanges::granges(out$peaks)
        frag <- .requireCall("Signac", "CreateFragmentObject")(
            out$fragments, cells = stats::setNames(colnames(so), colnames(so)), verbose = FALSE)
        atacCounts <- .requireCall("Signac", "FeatureMatrix")(
            frag, features = pk, cells = colnames(so), verbose = FALSE)
        so[["ATAC"]] <- .requireCall("Signac", "CreateChromatinAssay")(
            atacCounts, fragments = frag, ranges = pk, validate.fragments = FALSE)
        lg <- .stringToRanges(out$links$peak)
        mid <- (GenomicRanges::start(lg) + GenomicRanges::end(lg)) %/% 2
        tss <- out$genes$genes$tss[match(out$links$gene, out$genes$genes$gene_name)]
        L <- GenomicRanges::GRanges("chr1", IRanges::IRanges(pmin(mid, tss), pmax(mid, tss)))
        L$score <- out$links$score; L$gene <- out$links$gene
        L$peak <- out$links$peak; L$pvalue <- out$links$pvalue
        setLinks <- getExportedValue("Signac", "Links<-")
        atacAssay <- setLinks(so[["ATAC"]], value = L)
        so[["ATAC"]] <- atacAssay
        out$object <- so
    }
    out
}

.isContrastSpec <- function(x, md) {
    is.character(x) && length(x) == 3 && x[1] %in% names(md)
}

#' Run LocusPick on single-cell data
#'
#' The single-cell counterpart of [locusPick()], for multiome data (RNA and
#' ATAC from the same cells) or paired scRNA-seq + scATAC-seq of the same
#' samples. For each cell type, it tests the requested contrasts with
#' pseudobulk DE ([pseudobulkDE()]), builds accessibility tracks per condition
#' from the fragments files ([scSignal()]), links peaks to genes (with
#' multiome peak-gene links when available, otherwise by distance), and ranks
#' candidate loci within each cell type and group.
#'
#' @param rna Object with gene expression: Seurat, `SingleCellExperiment`,
#'   [read10x()] result, or a genes x cells count matrix (with `meta`).
#' @param atac Object with chromatin accessibility. For multiome data, the same
#'   object as `rna` (the default). For unpaired data, a separate Signac object,
#'   [read10x()] result, or `NULL` with `fragments` and `atacMeta`.
#' @param cellType Metadata column with cell types (in both objects).
#' @param sample Metadata column with biological samples (in both objects).
#' @param perturbation,condition Contrasts as `c(column, test, reference)`,
#'   e.g. `c("genotype", "KO", "WT")` and `c("age", "old", "young")`, tested
#'   with pseudobulk DE. Alternatively a DE table used for every cell type, or
#'   a named list of DE tables per cell type. Either or both may be `NULL`.
#' @param genes Gene models (GTF path, `GRanges`, or [readGeneModels()]).
#' @param peaks Peaks; default: the peak set of `atac`.
#' @param links Peak-gene links: `"auto"` (use `Signac::Links()` of `atac`
#'   when present), `NULL` (distance-based assignment), or a table.
#' @param fragments Fragments file(s), if not stored in `atac`.
#' @param meta,atacMeta Optional cell metadata for `rna` and `atac` (needed for
#'   matrices and 10x folders).
#' @param rnaAssay,atacAssay Assays to use. By default the default assay of
#'   `rna` (or `RNA` if the default holds peaks) and the first chromatin assay
#'   of `atac`.
#' @param cellTypes Optional subset of cell types.
#' @param method Pseudobulk DE method, `"DESeq2"` or `"edgeR"`.
#' @param covariates Optional sample-level columns adjusted for in pseudobulk
#'   DE (e.g. `"genotype"` when testing only age in a two-factor design). When
#'   both contrasts are given, each is adjusted for the other automatically.
#' @param minCells,minSamples Minimum cells per pseudobulk / track, and samples
#'   per condition.
#' @param backgroundPeaks Number of peaks sampled per cell type to test
#'   whether signal changes are specific ([signalShift()]).
#' @param mappability,orgDb,weights,alpha,minLFC,perturbationType,maxDist,maxLinkDist,minMappability,n
#'   As in [locusPick()].
#' @return A `LocusPickResult` (see [locusPick()]) with an extra
#'   `cell_type` column; groups are named `<cell type> | <group>`.
#' @examples
#' sc <- locusPickSingleCellExample()
#' res <- scLocusPick(sc$rna, atac = NULL, cellType = "cell_type", sample = "sample",
#'                    perturbation = c("genotype", "KO", "WT"),
#'                    condition = c("age", "old", "young"),
#'                    genes = sc$genes, peaks = sc$peaks, links = sc$links,
#'                    fragments = sc$fragments, meta = sc$meta, atacMeta = sc$meta)
#' res
#' @export
scLocusPick <- function(rna, atac = rna, cellType, sample, perturbation = NULL,
                        condition = NULL, genes, peaks = NULL, links = "auto",
                        fragments = NULL, meta = NULL, atacMeta = meta,
                        rnaAssay = NULL, atacAssay = NULL, cellTypes = NULL,
                        method = c("DESeq2", "edgeR"), covariates = NULL,
                        minCells = 10, minSamples = 2,
                        backgroundPeaks = 2000, mappability = NULL, orgDb = NULL,
                        weights = NULL, alpha = 0.05, minLFC = 0,
                        perturbationType = c("loss", "gain"), maxDist = 5000,
                        maxLinkDist = 5e5, minMappability = 0.8, n = 10) {
    method <- match.arg(method)
    perturbationType <- match.arg(perturbationType)
    harm <- if (!is.null(orgDb)) function(s) harmonizeSymbols(s, orgDb) else NULL

    message("== Reading inputs")
    if (.isSeurat(rna) && is.null(rnaAssay)) {
        rnaAssay <- .scAssay(rna, NULL, "rna")
        if (.isChromatinAssay(rna, rnaAssay)) {
            if (!"RNA" %in% names(rna@assays))
                stop("The default assay '", rnaAssay, "' holds peaks; set `rnaAssay`.",
                     call. = FALSE)
            message("  Default assay '", rnaAssay, "' holds peaks; using 'RNA' for expression.")
            rnaAssay <- "RNA"
        }
    }
    mdR <- .scMeta(rna, meta, cells = colnames(.scCounts(rna, rnaAssay)))
    .stopIfMissingCols(mdR, c(cellType, sample), "RNA cell metadata")
    gm <- if (inherits(genes, "locusGeneModels")) genes else readGeneModels(genes, harmonize = harm)

    # --- peaks and links
    if (is.null(peaks)) {
        peaks <- if (!is.null(atac) && .isSeurat(atac)) {
            a <- .scAssay(atac, atacAssay, "atac")
            GenomicRanges::granges(atac[[a]])
        } else if (inherits(atac, "LocusPick10x")) atac$peaks else
            stop("Give `peaks` (none found in `atac`).", call. = FALSE)
    }
    pk <- readPeaks(peaks, verbose = FALSE)
    if (identical(links, "auto")) {
        links <- NULL
        if (!is.null(atac) && .isSeurat(atac)) {
            a <- .scAssay(atac, atacAssay, "atac")
            L <- tryCatch(.requireCall("Signac", "Links")(atac[[a]]), error = function(e) NULL)
            if (length(L)) {
                links <- L
                message("  Using ", length(L), " peak-gene links from the '", a, "' assay.")
            }
        }
        if (is.null(links)) message("  No peak-gene links: assigning peaks to the nearest gene.")
    }

    # --- DE per cell type
    pbObj <- NULL
    deFor <- function(spec, other) {
        if (is.null(spec)) return(NULL)
        if (.isContrastSpec(spec, mdR)) {
            cov <- unique(c(covariates, if (.isContrastSpec(other, mdR)) other[1]))
            message("== Pseudobulk DE (", method, "): ", spec[1], " ", spec[2], " vs ", spec[3])
            if (is.null(pbObj))
                pbObj <<- pseudobulk(rna, sample = sample, cellType = cellType, meta = meta,
                                     assay = rnaAssay, minCells = minCells)
            d <- pseudobulkDE(pbObj, contrast = spec, method = method, covariates = cov,
                              minSamples = minSamples, cellTypes = cellTypes)
            if (!is.null(harm)) for (ct in names(d)) d[[ct]]$gene <- harm(d[[ct]]$gene)
            return(d)
        }
        if (is.data.frame(spec) || !is.list(spec)) return(list(.all = .readDEfor(spec, orgDb, NULL)))
        lapply(spec, .readDEfor, orgDb = orgDb, direction = NULL)
    }
    pert <- deFor(perturbation, condition)
    cond <- deFor(condition, perturbation)

    # --- signal: one track per cell type x level of the condition (or perturbation)
    sigCol <- if (.isContrastSpec(condition, mdR)) condition else
        if (.isContrastSpec(perturbation, mdR)) perturbation else NULL
    mdA <- if (is.null(atac)) {
        m <- if (is.null(atacMeta)) stop("Give `atacMeta` when `atac` is NULL.", call. = FALSE) else
            as.data.frame(atacMeta)
        if ("barcode" %in% names(m)) rownames(m) <- m$barcode
        m
    } else .scMeta(atac, atacMeta)
    groupBy <- c(cellType, if (!is.null(sigCol)) sigCol[1])
    message("== Accessibility tracks")
    sig <- scSignal(atac, groupBy, fragments = fragments, meta = if (is.null(atac)) mdA else atacMeta,
                    assay = atacAssay, minCells = minCells)
    sigInfo <- attr(sig, "groups")
    levelsOrder <- if (!is.null(sigCol)) c(sigCol[3], sigCol[2]) else NULL

    cts <- unique(as.character(mdR[[cellType]]))
    if (!is.null(cellTypes)) cts <- intersect(cts, cellTypes)
    cts <- intersect(cts, sigInfo[[cellType]])

    # --- per cell type
    message("== Building candidates per cell type")
    pick <- function(d, ct) if (is.null(d)) NULL else if (".all" %in% names(d)) d$.all else d[[ct]]
    allCand <- list(); shifts <- list(); tracksByCt <- list()
    for (ct in cts) {
        dP <- pick(pert, ct); dC <- pick(cond, ct)
        if ((!is.null(pert) && is.null(dP)) || (!is.null(cond) && is.null(dC))) {
            message("  ", ct, ": skipped (no DE results)"); next
        }
        groups <- if (is.null(dP) && is.null(dC)) NULL else
            suppressWarnings(defineGroups(dP, dC, alpha = alpha, minLFC = minLFC,
                                          perturbationType = perturbationType,
                                          conditionName = if (!is.null(sigCol)) sigCol[1] else "condition"))
        si <- sigInfo[sigInfo[[cellType]] == ct, , drop = FALSE]
        lvl <- if (!is.null(sigCol)) si[[sigCol[1]]] else "accessibility"
        if (!is.null(levelsOrder)) si <- si[order(match(lvl, levelsOrder)), , drop = FALSE]
        lvl <- if (!is.null(sigCol)) si[[sigCol[1]]] else "accessibility"
        trk <- stats::setNames(sig[si$track], lvl)
        tracksByCt[[ct]] <- si$track
        cand <- suppressWarnings(buildCandidates(
            pk, gm, groups, signal = trk, mappability = mappability, links = links,
            maxDist = maxDist, maxLinkDist = maxLinkDist, minMappability = minMappability))
        if (!nrow(cand)) { message("  ", ct, ": no candidates"); next }
        if (length(trk) >= 2)
            cand$signal_change <- cand[[paste0(lvl[1], "_mean")]] - cand[[paste0(lvl[2], "_mean")]]
        cand$cell_type <- ct
        cand$de_group <- as.character(cand$group)
        cand$group <- paste(ct, cand$group, sep = " | ")
        allCand[[ct]] <- cand
        if (length(trk) >= 2) {
            set.seed(1)
            bgp <- if (length(pk) > backgroundPeaks) pk[sort(sample(length(pk), backgroundPeaks))] else pk
            sh <- signalShift(cand, paste0(lvl[1], "_mean"), paste0(lvl[2], "_mean"),
                              background = signalAtPeaks(bgp, trk[1:2]))
            sh$group[sh$group == "background (all peaks)"] <- paste(ct, "| background (all peaks)")
            shifts[[ct]] <- sh
        }
        message(sprintf("  %s: %d candidate peak-gene pairs, %d eligible", ct, nrow(cand),
                        sum(cand$eligible)))
    }
    if (!length(allCand))
        stop("No cell type produced candidates: no significant genes linked to peaks. ",
             "Check the DE messages above; adjusting for other sample-level factors ",
             "(`covariates`), relaxing `alpha`, or ranking without DE may help.", call. = FALSE)
    cols <- unique(unlist(lapply(allCand, names)))
    cand <- do.call(rbind, lapply(allCand, function(d) {
        d[setdiff(cols, names(d))] <- NA; d[cols]
    }))
    cand$group <- factor(cand$group, levels = unique(cand$group))
    rownames(cand) <- NULL

    lv1 <- if (!is.null(sigCol)) sigCol[3] else "accessibility"
    if (is.null(weights)) {
        weights <- c(abs_lfc_perturbation = 1, abs_lfc_condition = 1)
        weights <- weights[names(weights) %in% names(cand)]
        weights <- c(stats::setNames(1, paste0(lv1, "_mean")), weights)
        if (!is.null(links)) weights <- c(weights, link_score = 1)
    }
    message(paste(strwrap(paste0("  ranking weights: ", paste(names(weights), unlist(weights),
                                                           sep = " = ", collapse = ", ")),
                          width = 78, exdent = 4), collapse = "\n"))
    ranked <- rankLoci(cand, weights)
    top <- topLoci(ranked, n = n)

    expression <- NULL
    if (!is.null(pbObj)) {
        specs <- Filter(function(z) .isContrastSpec(z, mdR), list(perturbation, condition))
        cd <- pbObj$colData
        # groups: every combination of the tested contrasts, reference levels first
        grp <- do.call(paste, lapply(specs, function(z) as.character(cd[[z[1]]])))
        lev <- do.call(paste, rev(expand.grid(lapply(rev(specs), function(z) c(z[3], z[2])),
                                              stringsAsFactors = FALSE)))
        expression <- expressionFrom(pbObj, group = grp, levels = lev)
    }
    ordTracks <- unlist(tracksByCt, use.names = FALSE)
    structure(list(candidates = ranked, top = top, qc = qcSummary(cand),
                   shift = if (length(shifts)) do.call(rbind, unname(shifts)) else NULL,
                   checks = NULL, groups = NULL, peaks = pk, genes = gm,
                   signal = sig[ordTracks], expression = expression,
                   trackGroups = list(Accessibility = ordTracks), weights = weights,
                   cellTypes = names(allCand), pseudobulk = pbObj,
                   contrasts = c(perturbation = .specLabel(perturbation),
                                 condition = .specLabel(condition))),
              class = "LocusPickResult")
}

.specLabel <- function(x) {
    if (is.null(x)) "none" else if (is.character(x) && length(x) == 3)
        paste(x[1], x[2], "vs", x[3], "(pseudobulk)") else "supplied DE results"
}
